#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
fail=0

assert() { if eval "$1" >/dev/null 2>&1; then echo "PASS: $2"; else echo "FAIL: $2"; fail=1; fi; }

assert "jq -e '.name == \"playbook\"' '$root/.claude-plugin/plugin.json'" "plugin.json name is playbook"
assert "jq -e '.version and .description and .license' '$root/.claude-plugin/plugin.json'" "plugin.json has core metadata"
assert "jq -e 'has(\"skills\") | not' '$root/.claude-plugin/plugin.json'" "plugin.json does NOT list skills (directory discovery)"
assert "jq -e '.plugins[0].name == \"playbook\" and .plugins[0].source == \"./\"' '$root/.claude-plugin/marketplace.json'" "marketplace lists playbook at ./"
assert "jq -e '.name == \"lujstn-playbook\"' '$root/.claude-plugin/marketplace.json'" "marketplace name is the production lujstn-playbook (not playbook-dev)"
assert "jq -e '.name | test(\"^[a-z0-9-]+$\")' '$root/.claude-plugin/marketplace.json'" "marketplace name is valid kebab-case (no @ or / that would break plugin@marketplace refs)"
assert "[ \"\$(jq -r '.version' '$root/.claude-plugin/plugin.json')\" = \"\$(jq -r '.plugins[0].version' '$root/.claude-plugin/marketplace.json')\" ]" "plugin.json and marketplace.json versions match"

assert "jq -e '[.hooks.Stop[].hooks[].command] | length == 1 and (.[0] | test(\"signal\"))' '$root/hooks/hooks.json'" "Stop carries only the signal hook (it records away, never re-prompts)"
assert "jq -e '.hooks.SubagentStop[0].hooks[0].command | test(\"signal\")' '$root/hooks/hooks.json'" "SubagentStop runs signal, so a review landing mid-turn arms the pause"
assert "jq -e '.hooks.PostToolUse[0].matcher == \"Edit|Write|MultiEdit|NotebookEdit|Bash|Read|Agent|SendMessage|AskUserQuestion|Workflow\"' '$root/hooks/hooks.json'" "PostToolUse reads payloads only for the tools the signals need"
assert "jq -e '.hooks.PostToolUse[0].hooks | map(.command) | any(test(\"signal\"))' '$root/hooks/hooks.json'" "PostToolUse wired to signal"
assert "jq -e '.hooks.PostToolBatch[0].hooks | map(.command) | any(test(\"take-a-beat\"))' '$root/hooks/hooks.json'" "PostToolBatch wired to take-a-beat"
assert "jq -e '.hooks.PostToolUseFailure[0].hooks | map(.command) | any(test(\"signal\"))' '$root/hooks/hooks.json'" "PostToolUseFailure wired to signal"
assert "jq -e '.hooks.UserPromptSubmit[0].hooks | map(.command) | any(test(\"take-a-beat\"))' '$root/hooks/hooks.json'" "UserPromptSubmit wired to take-a-beat"
assert "jq -e '.hooks.PreToolUse[0].matcher == \"Edit|Write|MultiEdit|NotebookEdit\"' '$root/hooks/hooks.json'" "the first PreToolUse entry matches the editing tools"
assert "jq -e '.hooks.PreToolUse[0].hooks | map(.command) | any(test(\"comment-guard\"))' '$root/hooks/hooks.json'" "PreToolUse wired to comment-guard"
assert "[ -x '$root/hooks/comment-guard' ]" "comment-guard is executable"
assert "[ ! -e '$root/hooks/comment-guard.sh' ]" "comment-guard is extensionless (the run-hook.cmd contract)"
assert "jq -e '.hooks.PreToolUse[0].hooks | map(.command) | any(test(\"signal\"))' '$root/hooks/hooks.json'" "the editing tools also reach signal (gates and interface checks)"
assert "jq -e '[.hooks.PreToolUse[] | select(.matcher == \"Bash|AskUserQuestion|Read\")][0].hooks | map(.command) | any(test(\"signal\"))' '$root/hooks/hooks.json'" "PreToolUse Bash, AskUserQuestion and Read wired to signal (the no-op channel, offline questions and the crew's interface)"
assert "jq -e '.hooks.PreToolUse[0].hooks | map(.command) | ((map(test(\"comment-guard\")) | index(true)) < (map(test(\"signal\")) | index(true)))' '$root/hooks/hooks.json'" "signal runs after comment-guard, so the veto still decides first"
assert "[ ! -e '$root/hooks/edit-log' ]" "edit-log is gone (signal counts only successful edits)"
assert "[ -x '$root/hooks/signal' ]" "signal is executable"
assert "[ -x '$root/hooks/team-idle' ]" "team-idle is executable"
assert "[ -x '$root/scripts/statusline' ]" "scripts/statusline is executable"
assert "jq -e '.hooks.TeammateIdle[0].hooks | map(.command) | any(test(\"team-idle\"))' '$root/hooks/hooks.json'" "TeammateIdle wired to team-idle"
assert "[ ! -e '$root/hooks/signal.sh' ] && [ ! -e '$root/hooks/team-idle.sh' ]" "signal and team-idle are extensionless (the run-hook.cmd contract)"
assert "! grep -q 'unease' '$root/hooks/hooks.json'" "no unease reference remains in hooks.json"
assert "! jq -e '.hooks.PreCompact or .hooks.PostCompact' '$root/hooks/hooks.json'" "PreCompact and PostCompact not registered (dead seam removed)"
assert "jq -e '.hooks.SessionStart[0].matcher | test(\"compact\")' '$root/hooks/hooks.json'" "SessionStart matcher includes compact (real re-anchor seam)"
assert "! grep -q 'uncertainty' '$root/hooks/hooks.json'" "no uncertainty reference in hooks.json"

assert "jq -e '.hooks.Notification[0].matcher == \"permission_prompt|idle_prompt|elicitation_dialog|elicitation_url_dialog|agent_needs_input|agent_completed|quota_auto_resume_stale|quota_auto_resume_disabled\"' '$root/hooks/hooks.json'" "Notification matcher covers every state that blocks on the user, plus idle and completed for the log"
assert "jq -e '.hooks.Notification[0].hooks | map(.command) | any(test(\"notification\"))' '$root/hooks/hooks.json'" "Notification wired to notification"
assert "jq -e '.hooks.Notification[0].hooks | map(.command) | any(test(\"signal\"))' '$root/hooks/hooks.json'" "Notification also reaches signal (away while the user is wanted)"
assert "[ \"\$(jq -r '.version' '$root/.claude-plugin/plugin.json')\" = 3.0.0 ]" "plugin version is 3.0.0"
assert "! grep -qi 'divide-by-ten\\|time rule\\|ultracode from over-reaching' '$root/.claude-plugin/plugin.json' '$root/.claude-plugin/marketplace.json'" "manifest descriptions drop the time rule and the ultracode restraint"
assert "jq -e '[.hooks.PreToolUse[] | select(.matcher == \"Agent|Workflow|SendMessage\")] | length == 1' '$root/hooks/hooks.json'" "PreToolUse has exactly one Agent|Workflow|SendMessage entry"
assert "jq -e '[.hooks.PreToolUse[] | select(.matcher == \"Agent|Workflow|SendMessage\")][0].hooks | map(.command) | any(test(\"dispatch-guard\"))' '$root/hooks/hooks.json'" "PreToolUse Agent|Workflow|SendMessage entry wired to dispatch-guard"
assert "[ -x '$root/hooks/notification' ]" "notification is executable"
assert "[ ! -e '$root/hooks/notification.sh' ]" "notification is extensionless (the run-hook.cmd contract)"
assert "[ -x '$root/hooks/dispatch-guard' ]" "dispatch-guard is executable"
assert "[ ! -e '$root/hooks/dispatch-guard.sh' ]" "dispatch-guard is extensionless (the run-hook.cmd contract)"
assert "[ -x '$root/scripts/offline' ]" "scripts/offline is executable"

assert "[ -d '$root/commands' ]" "commands/ directory exists"
assert "[ -f '$root/commands/fix.md' ]" "commands/fix.md present"
assert "[ -f '$root/commands/workflow.md' ]" "commands/workflow.md present"
assert "[ -f '$root/commands/hello.md' ]" "commands/hello.md present (the /playbook:hello entry point)"
assert "[ ! -f '$root/commands/pb.md' ] && [ ! -f '$root/commands/playbook.md' ]" "the pb/playbook heartbeat twins are gone (single hello command)"
assert "[ -f '$root/skills/setup/SKILL.md' ]" "setup skill present"
assert "[ -f '$root/skills/offline-mode/notify-setup.md' ]" "guided notification walkthrough present"
assert "[ -z \"\$(ls '$root'/commands/pb-*.md 2>/dev/null)\" ]" "no pb-* command files remain (plain and playbook: forms only)"
assert "grep -q 'disable-model-invocation: true' '$root/commands/workflow.md'" "workflow.md is user-only (disable-model-invocation: the Workflow-tool opt-in)"

exit $fail
